import Foundation
import Observation

/// A control tapped on the call's Live Activity — the Lock Screen card or the
/// Dynamic Island — arriving from an intent rather than from the interface.
/// `RootCallLifecycle` drains it onto `RobotCallController`.
///
/// **In memory rather than an App Group store, against this target's usual
/// rule.** Everything else here persists through the group because an extension
/// process is disposable; a `LiveActivityIntent` is the exception, because it
/// runs in the *app's* process. Mailbox and drainer are therefore the same
/// process, which is `CallRequestInbox`'s situation and not `RobotPowerCommand`'s.
/// Do not "correct" this into a group store: the app is right there, and a
/// round trip through disk would only add a way for the two to disagree.
///
/// A mailbox of its own rather than a second case on `CallRequestInbox`, which
/// carries a robot id, a time-to-live and a routing rule. "Mute the call that is
/// already up" has no use for any of the three — it addresses nothing, because
/// this app has exactly one call.
@MainActor
@Observable
public final class CallControlInbox {
    public enum Control: Equatable, Sendable {
        case toggleMute
        case end
    }

    public struct Pending: Equatable, Sendable {
        public let control: Control
        /// What makes two identical taps two events. Without it the second Mute
        /// in a row writes the value that is already there and `onChange` never
        /// fires — the reason `QuickActionInbox` and `CallRequestInbox` both
        /// carry one.
        public let token: Int
    }

    /// `shared` for the reason the other two mailboxes have one: the intent that
    /// fills it runs with no initialiser to inject through.
    public static let shared = CallControlInbox()

    public private(set) var pending: Pending?
    private var issued = 0

    public init() {}

    public func receive(_ control: Control) {
        issued += 1
        pending = Pending(control: control, token: issued)
    }

    /// `public` where `CallRequestInbox.drop()` is internal: that one is drained
    /// inside its own module and this one is drained from `ReachyUI`.
    public func drop() {
        pending = nil
    }
}

@testable import ReachyWidgetUI
import Testing

/// The mailbox the Live Activity's buttons post into. One property is worth
/// holding and it is the token: every `onChange` drain in `ReachyUI` rests on
/// two identical taps being two distinct `Equatable` values, and nothing else
/// in the type can fail in a way a test would see.
@Suite("Call control inbox")
@MainActor
struct CallControlInboxTests {
    @Test("two identical taps arrive as two distinct values")
    func identicalTapsAreDistinct() {
        let inbox = CallControlInbox()

        inbox.receive(.toggleMute)
        let first = inbox.pending
        inbox.receive(.toggleMute)

        #expect(first != inbox.pending)
        #expect(inbox.pending?.control == .toggleMute)
    }

    @Test("dropping clears the pending control")
    func droppingClears() {
        let inbox = CallControlInbox()
        inbox.receive(.end)

        inbox.drop()

        #expect(inbox.pending == nil)
    }
}

// A platform fork, not a version gate. `ActivityKit.framework` is present in the
// macOS SDK, which is the trap: every type in it is `@available(macOS,
// unavailable)` — checked in `arm64e-apple-macos.swiftinterface`, not assumed —
// so no macOS floor bump brings this back. `#if canImport(ActivityKit)` would be
// the wrong spelling; it is true under Catalyst, where these are still absent.
#if os(iOS)
    import ActivityKit
    import Foundation

    /// The call as the system's Live Activity sees it: a Lock Screen card and the
    /// three Dynamic Island regions, drawn from `CallActivityView`.
    ///
    /// Declared in this target because `ActivityAttributes` has to be the *same*
    /// type in two processes — the app that requests the activity and the
    /// extension that renders it — and this is the one target both link. Same
    /// placement rule as `RobotWidgetContent`.
    ///
    /// **`robotName` is static, not part of the state.** A robot change under an
    /// active call ends that call (`RobotCallController.robotChanged`), so the
    /// name cannot vary across one activity's life. And there is no robot id at
    /// all: this app has exactly one call at a time, so the buttons have nothing
    /// to address.
    public struct RobotCallAttributes: ActivityAttributes {
        /// The only thing that moves while a call is up.
        public struct ContentState: Codable, Hashable, Sendable {
            public var isMuted: Bool

            public init(isMuted: Bool) {
                self.isMuted = isMuted
            }
        }

        /// Nil where the daemon reports an empty name — the common case on a
        /// robot nobody has renamed, which the widget's own views already treat
        /// as ordinary rather than as an error.
        public let robotName: String?

        public init(robotName: String?) {
            self.robotName = robotName
        }
    }
#endif

// `LiveActivityIntent` is `@available(macOS, unavailable)` exactly as ActivityKit
// is; `CallActivityAttributes` carries the reasoning.
#if os(iOS)
    import AppIntents

    /// The two buttons on the call's Live Activity.
    ///
    /// **Here rather than in the app target, and the `CallRobotIntent` reasoning
    /// does not transfer.** That one lives beside the app because
    /// `openAppWhenRun` errors in an appex; these set no such flag. What decides
    /// their home is that the *extension* renders `Button(intent:)` and so must
    /// be able to name the type, while the *app* has to contain it to run it —
    /// and `ReachyWidgetUI` is the one target both link.
    ///
    /// **`LiveActivityIntent`, not a plain `AppIntent`, and that is the whole
    /// mechanism.** It runs in the app's own process, which is what lets a
    /// button drawn by the extension reach `RobotCallController` — a type this
    /// target cannot even name, because it lives in `ReachyMedia`. The hop is
    /// `CallControlInbox`, drained by `RootCallLifecycle`.
    ///
    /// Both are `isDiscoverable = false`: they are the activity's own
    /// bookkeeping, not something to offer in Shortcuts — and `ReachyShortcuts`
    /// is at ten of ten phrases, so a discoverable one would have to displace
    /// something. The flag does **not** keep them out of `Metadata.appintents`;
    /// `Scripts/check-appintents-metadata.sh` holds both names for that reason.
    public struct CallMuteIntent: LiveActivityIntent {
        public static let title: LocalizedStringResource = "Mute the Reachy Mini call"
        public static let isDiscoverable = false

        public init() {}

        @MainActor
        public func perform() async throws -> some IntentResult {
            CallControlInbox.shared.receive(.toggleMute)
            return .result()
        }
    }

    public struct CallEndIntent: LiveActivityIntent {
        public static let title: LocalizedStringResource = "End the Reachy Mini call"
        public static let isDiscoverable = false

        public init() {}

        @MainActor
        public func perform() async throws -> some IntentResult {
            CallControlInbox.shared.receive(.end)
            return .result()
        }
    }
#endif

import OSLog
import ReachyWidgetUI

#if os(iOS)
    import ActivityKit
#endif

/// Starts, updates and ends the call's Live Activity.
///
/// **Here because this is the only floor that can see both sides.**
/// `RobotCallAttributes` lives in `ReachyWidgetUI` and `RobotCallController` in
/// `ReachyMedia`, and the widget target is forbidden from linking the media one
/// (`Package.swift`). `ReachyUI` links both, so the join has exactly one legal
/// home and this is it.
///
/// **It stores nothing, deliberately.** `Activity.activities` *is* the handle,
/// so there is no `@State` to thread through `ReachyRootView` and no `shared` to
/// keep in step with the call. That falls out into a fix rather than a cost: an
/// app killed mid-call leaves a Lock Screen card carrying two live buttons and
/// no call behind them, and `start` sweeps any stray before requesting a new
/// one. Nothing else notices such a card, because nothing else is looking.
///
/// The cross-platform surface with `#if os(iOS)` bodies is `RobotCallController`'s
/// shape, for its reason: no caller carries a fork of its own, and on macOS —
/// where ActivityKit is unavailable outright — all three are honest no-ops,
/// because no call ever becomes active there either.
@MainActor
enum CallLiveActivity {
    /// A call became active. Any refusal is swallowed and logged: Live Activities
    /// are a per-app switch in Settings, and somebody who turned them off must
    /// not lose the call over its garnish — the trade `CallLifecycle.startFailed`
    /// already records for the call framing itself.
    static func start(robotName: String?, isMuted: Bool) {
        #if os(iOS)
            Task { @MainActor in
                await endEvery()
                do {
                    _ = try Activity.request(
                        attributes: RobotCallAttributes(robotName: robotName),
                        content: ActivityContent(
                            state: RobotCallAttributes.ContentState(isMuted: isMuted),
                            staleDate: nil
                        )
                    )
                } catch {
                    log.notice("Live Activity refused: \(String(describing: error), privacy: .public)")
                }
            }
        #endif
    }

    static func update(isMuted: Bool) {
        #if os(iOS)
            Task { @MainActor in
                let content = ActivityContent(
                    state: RobotCallAttributes.ContentState(isMuted: isMuted),
                    staleDate: nil
                )
                for activity in Activity<RobotCallAttributes>.activities {
                    await activity.update(content)
                }
            }
        #endif
    }

    static func end() {
        #if os(iOS)
            Task { @MainActor in await endEvery() }
        #endif
    }

    #if os(iOS)
        private static let log = Logger(
            subsystem: "com.alexey1312.ReachyMini", category: "CallActivity"
        )

        /// `.immediate` rather than the default, which leaves the card on the Lock
        /// Screen for hours after the hang-up. For a call that reads as a bug —
        /// and `staleDate` is not the alternative, because it greys a card out
        /// instead of removing it and would have to be re-armed on every update.
        private static func endEvery() async {
            for activity in Activity<RobotCallAttributes>.activities {
                await activity.end(nil, dismissalPolicy: .immediate)
            }
        }
    #endif
}

