// Named types from ActivityKit's neighbourhood — `Button(intent:)` over a
// `LiveActivityIntent` — so the whole file forks with them.
// `CallActivityAttributes` carries why that fork is platform and not version.
#if os(iOS)
    import AppIntents
    import ReachyDesign
    import SwiftUI

    /// The call's Live Activity, in the pieces the system asks for separately: a
    /// Lock Screen card, three Dynamic Island regions, and the two glyphs it
    /// shows when the island is not expanded.
    ///
    /// **Every piece takes plain values, never `RobotCallAttributes.ContentState`.**
    /// That is what lets the previews and the snapshot suite render them as
    /// ordinary views — the same trade `RobotWidgetView` makes by taking its
    /// layout as a parameter instead of reading `\.widgetFamily`. The
    /// `ActivityConfiguration` that assembles them lives in the extension
    /// (`Apps/ReachyWidget/Sources/RobotCallActivity.swift`) and is the only
    /// thing here that cannot be captured headless.
    ///
    /// **Nothing draws the call's duration**, and that is deliberate rather than
    /// an omission: `Text(_:style: .timer)` renders live in a real activity and
    /// as a frozen arbitrary string in a capture, so every reference image would
    /// churn on every run. The system's own call pill already shows it.
    public struct CallActivityCard: View {
        private let robotName: String?
        private let isMuted: Bool

        public init(robotName: String?, isMuted: Bool) {
            self.robotName = robotName
            self.isMuted = isMuted
        }

        public var body: some View {
            HStack(spacing: Space.md) {
                CallActivityStatus(robotName: robotName, isMuted: isMuted)
                Spacer(minLength: Space.sm)
                CallActivityControls(isMuted: isMuted)
            }
            .padding(Space.md)
        }
    }

    /// Who is on the call and whether they can hear you. Shared by the card and
    /// the island's leading region, which ask the same question with different
    /// room to answer it.
    public struct CallActivityStatus: View {
        private let robotName: String?
        private let isMuted: Bool

        public init(robotName: String?, isMuted: Bool) {
            self.robotName = robotName
            self.isMuted = isMuted
        }

        public var body: some View {
            HStack(spacing: Space.sm) {
                Image(systemName: "video.fill")
                    .foregroundStyle(Tone.brand.style)
                VStack(alignment: .leading, spacing: Space.xxs) {
                    // A robot nobody renamed reports an empty name, which is the
                    // ordinary case rather than a failure — the widget's other
                    // views already treat it that way.
                    Text(robotName.map { Text($0) } ?? Text(.reachy("Reachy Mini")))
                        .font(Typography.rowTitle)
                        .lineLimit(1)
                    Text(isMuted ? .reachy("Microphone off") : .reachy("On a call"))
                        .font(Typography.status)
                        .foregroundStyle(Tone.quiet.style)
                }
            }
        }
    }

    /// Mute and End. Both post into `CallControlInbox`; neither knows what a call
    /// is — see `CallControlIntents` for why that indirection is the whole point.
    public struct CallActivityControls: View {
        private let isMuted: Bool

        public init(isMuted: Bool) {
            self.isMuted = isMuted
        }

        public var body: some View {
            HStack(spacing: Space.sm) {
                CallActivityMuteButton(isMuted: isMuted)
                CallActivityEndButton()
            }
        }
    }

    /// `CallActivityMuteButton`, not `CallMuteButton`: `CameraViewport` already
    /// has a `CallEndButton` in `ReachyUI`, and two names one grep apart is how
    /// the wrong one gets edited.
    public struct CallActivityMuteButton: View {
        private let isMuted: Bool

        public init(isMuted: Bool) {
            self.isMuted = isMuted
        }

        public var body: some View {
            Button(intent: CallMuteIntent()) {
                Label(
                    isMuted ? .reachy("Unmute microphone") : .reachy("Mute microphone"),
                    systemImage: isMuted ? "mic.slash.fill" : "mic.fill"
                )
                .labelStyle(.iconOnly)
            }
            .tint(isMuted ? Tone.warning.style : Tone.quiet.style)
        }
    }

    public struct CallActivityEndButton: View {
        public init() {}

        public var body: some View {
            Button(intent: CallEndIntent()) {
                Label(.reachy("End call"), systemImage: "phone.down.fill")
                    .labelStyle(.iconOnly)
            }
            .tint(Tone.danger.style)
        }
    }

    /// The island when it is not expanded: one glyph, and the system decides how
    /// much of it survives.
    public struct CallActivityGlyph: View {
        public enum Kind: Sendable, Equatable {
            /// Left of the aperture — that a call is up.
            case call
            /// Right of it — whether the microphone is open.
