import Foundation

/// Every decision the call makes, as a pure reducer.
///
/// The model the user chose (issue #78): a call *starts* when the microphone is
/// unmuted — "call the robot" is literally what opening the camera tab and
/// unmuting is. Muting during a call does not end it (an ordinary in-call mute);
/// the call ends from an End button — the viewport's or the Live Activity's —
/// or from the session becoming ineligible (robot asleep, stream failed,
/// viewport target gone). Passive viewing is never a call.
///
/// The invariant every path holds: **the microphone is live only while a call is
/// active.** Each ending effect list carries `.applyMic(false)`.
///
/// **This used to negotiate with LiveCommunicationKit and no longer does.** The
/// system drew the call as a compact pill it would never expand, with nothing on
/// the Lock Screen — measured, in `ReachyMedia/AGENTS.md` — so the framing moved
/// to an ActivityKit Live Activity, which does expand and does carry buttons.
/// What went with the framework: the `performed*` round trips, fulfilling and
/// failing system actions, reporting connection state, and the audio-session
/// handover. What stayed is every decision that was ever the app's own.
struct CallLifecycle: Equatable, Sendable {
    enum State: Equatable, Sendable {
        case idle
        /// A start was requested and the permission ask is in flight.
        case starting
        case active
    }

    private(set) var state: State = .idle

    enum Event: Equatable, Sendable {
        /// The mic button, an End-less redial, or the Live Activity's unmute.
        case unmuteTapped
        /// The mic button asked for silence. Inside a call this is an ordinary
        /// in-call mute and never an ending.
        case muteTapped
        /// An End button — the viewport's, or the Live Activity's.
        case endTapped
        /// The permission ask came back granted; the call is on.
        case micPermissionGranted
        /// The permission ask came back refused.
        case micPermissionDenied
        /// The session under the call went away: robot asleep, stream failed, or
        /// no viewport target left.
        case sessionBecameIneligible
    }

    enum Effect: Equatable, Sendable {
        /// Ask for the microphone permission; the answer arrives as
        /// `micPermissionGranted` or `micPermissionDenied`.
        case requestMicPermissionThenStart
        /// Actually flip the microphone track.
        case applyMic(Bool)
        /// Donate the start-call intent so Siri has something to hand back.
        /// Without CallKit there is no Phone Recents entry any more, but the
        /// donation still feeds Siri's suggestions and `onContinueUserActivity`.
        case donate
    }

    mutating func handle(_ event: Event) -> [Effect] {
        switch event {
        case .unmuteTapped: unmuteTapped()
        case .muteTapped: muteTapped()
        case .endTapped: endTapped()
        case .micPermissionGranted: micPermissionGranted()
        case .micPermissionDenied: startAbandoned()
        case .sessionBecameIneligible: becameIneligible()
        }
    }

    private mutating func unmuteTapped() -> [Effect] {
        switch state {
        case .idle:
            state = .starting
            return [.requestMicPermissionThenStart]
        case .starting:
            // Double tap while the permission ask runs: one start is enough.
            return []
        case .active:
            // An unmute inside a call is the other half of the in-call mute.
            return [.applyMic(true)]
        }
    }

    private mutating func muteTapped() -> [Effect] {
        switch state {
        case .idle:
            // Defensive: a live mic with no call should not exist, but a mute
            // request must always be able to mute.
            [.applyMic(false)]
        case .starting:
            // The permission ask is already out; landing active-and-unmuted and
            // letting the next tap mute is simpler than a cancel path for a
            // window measured in milliseconds.
            []
        case .active:
            [.applyMic(false)]
        }
    }

    /// The only thing that ends a call on purpose. `.starting` is accepted too:
    /// the permission sheet can be answered after the reader has changed their
    /// mind, and there is nothing to tear down yet.
    private mutating func endTapped() -> [Effect] {
        guard state != .idle else { return [] }
        state = .idle
        return [.applyMic(false)]
    }

    /// Permission granted, so the call is on. `.donate` rides here rather than
    /// on the tap, because a refused microphone is not a call worth suggesting.
    private mutating func micPermissionGranted() -> [Effect] {
        guard state == .starting else { return [] }
        state = .active
        return [.applyMic(true), .donate]
    }

    /// The permission was refused: the call never happened and the mic must stay
    /// shut. There is nothing to undo.
    private mutating func startAbandoned() -> [Effect] {
        guard state == .starting else { return [] }
        state = .idle
        return []
    }

    private mutating func becameIneligible() -> [Effect] {
        guard state != .idle else { return [] }
        state = .idle
        return [.applyMic(false)]
    }
}

