import Foundation
import Observation
import OSLog

/// Frames the two-way WebRTC session as a call (issue #78): a Live Activity on
/// the Lock Screen and in the Dynamic Island, with Mute and End on it.
/// `CameraSession` keeps doing the media work.
///
/// Every decision lives in `CallLifecycle`, which is tested; this class is the
/// adapter that owns the microphone permission round trip and the identity of
/// whoever is being called.
///
/// **There is no `#if os(iOS)` here any more, and its absence is the point.**
/// This used to be a platform fork over LiveCommunicationKit, which is
/// macOS-unavailable. That framework is gone — it drew a compact pill the system
/// would never expand, then drew it beside the Live Activity that does expand,
/// so one call showed as two indicators. What is left is ordinary cross-platform
/// code, so macOS now runs the same call model instead of degrading to a bare
/// microphone toggle. Only the Live Activity itself is iOS-only, and it lives in
/// `ReachyWidgetUI`.
@MainActor
@Observable
public final class RobotCallController {
    /// The call the app is currently showing, if any.
    public struct ActiveCall: Equatable, Sendable {
        /// `RobotIdentity.deduplicationKey` — rule 4, identity never an address.
        public let robotID: String
        public let robotName: String?
    }

    public private(set) var activeCall: ActiveCall?

    /// Bumped once per started call — the moment the start-call intent should be
    /// donated. The UI layer watches this and reads `activeCall` for the who.
    public private(set) var donationCount = 0

    /// True from the tap that asks for the microphone until the call is over —
    /// the window `hasActiveCall` misses, because the permission round trip
    /// happens first. Suspending the viewport in that window destroys the
    /// `CameraSession` the call is placed over; `AGENTS.md` has the reasoning.
    public private(set) var keepsSessionAlive = false

    public var hasActiveCall: Bool {
        activeCall != nil
    }

    @ObservationIgnored private var currentRobotID: String?
    @ObservationIgnored private var currentRobotName: String?
    @ObservationIgnored private var lifecycle = CallLifecycle()
    /// Weak: `ViewportModel` owns the session and drops it when the viewport
    /// suspends. `keepsSessionAlive` is what keeps that from happening under a
    /// call, so an effect landing on nil means the gate was bypassed.
    @ObservationIgnored private weak var session: CameraSession?

    /// The whole call chain logs here, because it shipped once with every
    /// failure swallowed and the mic button read as dead. Read it in Console
    /// with subsystem `com.alexey1312.ReachyMini`. **Nothing here may be
    /// `.debug`** — the log store drops that level, so such a line is absent
    /// from the field report it was written for.
    private static let log = Logger(subsystem: "com.alexey1312.ReachyMini", category: "RobotCall")

    public init() {}

    #if DEBUG
        /// A controller reporting an active call without any of the round trips.
        /// The only way a preview can capture a call-dependent control.
        public static func preview(robotName: String? = nil) -> RobotCallController {
            let controller = RobotCallController()
            controller.activeCall = ActiveCall(robotID: "preview-robot", robotName: robotName)
            return controller
        }
    #endif

    /// Keeps the controller pointed at the connected robot; a robot change under
    /// an active call ends the call — the far side of it is gone.
    public func robotChanged(id: String?, name: String?) {
        currentRobotID = id
        currentRobotName = name
        if let activeCall, activeCall.robotID != id {
            Self.log.notice("Ending the call: the robot changed")
            run(lifecycle.handle(.sessionBecameIneligible))
        }
    }

    /// The mic button's one entry point. An unmute with no call *is* placing the
    /// call; a mute inside one is an ordinary in-call mute.
    public func toggleMic(for session: CameraSession) {
        self.session = session
        run(lifecycle.handle(session.isMicEnabled ? .muteTapped : .unmuteTapped))
    }

    /// The redial path: a Siri phrase landed, the stream is up, unmute as if the
    /// button had been tapped.
    public func startCall(for session: CameraSession) {
        guard !session.isMicEnabled else { return }
        self.session = session
        run(lifecycle.handle(.unmuteTapped))
    }

    /// An End button — the viewport's, or the Live Activity's. Both land here so
    /// the two surfaces cannot disagree about whether a call is up.
    public func endCall() {
        guard lifecycle.state != .idle else { return }
        Self.log.notice("Ending the call: End was tapped")
        run(lifecycle.handle(.endTapped))
    }

    /// The session under the call went away — robot asleep or disconnected,
    /// stream failed, viewport target gone.
    public func sessionBecameIneligible() {
        guard lifecycle.state != .idle else { return }
        Self.log.notice("Ending the call: the session under it went away")
        run(lifecycle.handle(.sessionBecameIneligible))
    }

    // MARK: - Reducer effects

    private func run(_ effects: [CallLifecycle.Effect]) {
        for effect in effects {
            perform(effect)
        }
        // Postcondition, not an effect: `activeCall` and `keepsSessionAlive`
        // mirror the reducer so the viewport gate, the Live Activity and the
        // donation watcher all read one truth.
        if lifecycle.state == .active, activeCall == nil, let robotID = currentRobotID {
            activeCall = ActiveCall(robotID: robotID, robotName: currentRobotName)
        } else if lifecycle.state != .active {
            activeCall = nil
        }
        keepsSessionAlive = lifecycle.state != .idle
    }

    private func perform(_ effect: CallLifecycle.Effect) {
        switch effect {
        case .requestMicPermissionThenStart:
