        Task { @MainActor in
            let permission = await MicrophonePermission.request()
            guard permission == .granted else {
                Self.log.notice("Call abandoned: microphone permission refused")
                // Surfaces the existing blocked-button state on the viewport.
                session?.refreshMicPermission()
                run(lifecycle.handle(.micPermissionDenied))
                return
            }
            guard currentRobotID != nil else {
                Self.log.error("Call abandoned: no connected robot identity to call")
                run(lifecycle.handle(.micPermissionDenied))
                return
