@testable import ReachyMedia
import Testing

/// The whole of the call's decision table (issue #78). The reducer holds every
/// rule worth having: one start per call, mute never ends one, and **every**
/// path out of a call closes the microphone.
///
/// It used to be described as "the only part of the LiveCommunicationKit
/// integration a test can hold". That framework is gone, so this is no longer a
/// consolation prize — it is the whole of the call logic, and nothing about a
/// call now needs a device to exercise.
@Suite("Call lifecycle")
struct CallLifecycleTests {
    @Test("an unmute with no call asks for the microphone")
    func unmuteAsksForPermission() {
        var lifecycle = CallLifecycle()

        #expect(lifecycle.handle(.unmuteTapped) == [.requestMicPermissionThenStart])
        #expect(lifecycle.state == .starting)
    }

    @Test("a second unmute while starting asks once")
    func doubleTapAsksOnce() {
        var lifecycle = CallLifecycle()
        _ = lifecycle.handle(.unmuteTapped)

        #expect(lifecycle.handle(.unmuteTapped) == [])
        #expect(lifecycle.state == .starting)
    }

    /// The donation rides on the grant rather than on the tap: a refused
    /// microphone is not a call worth suggesting back to anybody.
    @Test("permission granted opens the microphone and donates")
    func grantedStartsTheCall() {
        var lifecycle = CallLifecycle()
        _ = lifecycle.handle(.unmuteTapped)

        #expect(lifecycle.handle(.micPermissionGranted) == [.applyMic(true), .donate])
        #expect(lifecycle.state == .active)
    }

    @Test("permission refused leaves the microphone shut")
    func refusedAbandonsTheStart() {
        var lifecycle = CallLifecycle()
        _ = lifecycle.handle(.unmuteTapped)

        #expect(lifecycle.handle(.micPermissionDenied) == [])
        #expect(lifecycle.state == .idle)
    }

    @Test("a grant with no start in flight does nothing")
    func strayGrantIsIgnored() {
        var lifecycle = CallLifecycle()

        #expect(lifecycle.handle(.micPermissionGranted) == [])
        #expect(lifecycle.state == .idle)
    }

    /// The rule the whole model rests on: muting is an ordinary in-call mute.
    @Test("a mute inside a call does not end it")
    func muteDoesNotEndTheCall() {
        var lifecycle = CallLifecycle.active()

        #expect(lifecycle.handle(.muteTapped) == [.applyMic(false)])
        #expect(lifecycle.state == .active)
    }

    @Test("an unmute inside a call reopens the microphone")
    func unmuteInsideACallReopens() {
        var lifecycle = CallLifecycle.active()
        _ = lifecycle.handle(.muteTapped)

        #expect(lifecycle.handle(.unmuteTapped) == [.applyMic(true)])
        #expect(lifecycle.state == .active)
    }

    @Test("End closes the microphone and the call")
    func endClosesBoth() {
        var lifecycle = CallLifecycle.active()

        #expect(lifecycle.handle(.endTapped) == [.applyMic(false)])
        #expect(lifecycle.state == .idle)
    }

    /// The permission sheet can be answered after the reader changed their mind,
    /// so End has to be accepted before the call is up.
    @Test("End while starting abandons the start")
    func endWhileStartingAbandons() {
        var lifecycle = CallLifecycle()
        _ = lifecycle.handle(.unmuteTapped)

        #expect(lifecycle.handle(.endTapped) == [.applyMic(false)])
        #expect(lifecycle.state == .idle)
    }

    @Test("End with no call does nothing")
    func endWithNoCallDoesNothing() {
        var lifecycle = CallLifecycle()

        #expect(lifecycle.handle(.endTapped) == [])
        #expect(lifecycle.state == .idle)
    }

    @Test("the session going away ends the call")
    func ineligibleSessionEndsTheCall() {
        var lifecycle = CallLifecycle.active()

        #expect(lifecycle.handle(.sessionBecameIneligible) == [.applyMic(false)])
        #expect(lifecycle.state == .idle)
    }

    @Test("an ineligible session with no call does nothing")
    func ineligibleWithNoCallDoesNothing() {
        var lifecycle = CallLifecycle()

        #expect(lifecycle.handle(.sessionBecameIneligible) == [])
        #expect(lifecycle.state == .idle)
    }

    /// The invariant, asserted over every ending rather than one at a time: a
    /// path out of a call that forgets `.applyMic(false)` leaves the microphone
    /// live with nothing on screen saying so.
    @Test("every path out of a call closes the microphone")
    func everyEndingClosesTheMicrophone() {
        for ending in [CallLifecycle.Event.endTapped, .sessionBecameIneligible] {
            var lifecycle = CallLifecycle.active()

            let effects = lifecycle.handle(ending)

            #expect(effects.contains(.applyMic(false)), "\(ending) left the microphone open")
            #expect(lifecycle.state == .idle, "\(ending) did not end the call")
        }
    }

    /// A mute is not an ending, so it is the one event that must *not* satisfy
    /// the rule above. Asserted so the loop cannot quietly grow to cover it.
    @Test("a mute is not an ending")
    func muteIsNotAnEnding() {
        var lifecycle = CallLifecycle.active()

        _ = lifecycle.handle(.muteTapped)

        #expect(lifecycle.state == .active)
    }
}

private extension CallLifecycle {
    /// A call that has been placed and answered — the state most rules are about.
    static func active() -> CallLifecycle {
        var lifecycle = CallLifecycle()
        _ = lifecycle.handle(.unmuteTapped)
        _ = lifecycle.handle(.micPermissionGranted)
        return lifecycle
    }
}
